package guards

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// TestGeneratedFilesAreDeclaredGenerated fails when a file produced by a cidx
// command and held current by a test is not marked linguist-generated.
//
// A review that counts generated files apart reads the declaration in
// .gitattributes: the header of the file is not in a patch that only changes
// cells.
func TestGeneratedFilesAreDeclaredGenerated(t *testing.T) {
	body, err := os.ReadFile(filepath.Join(projectRoot, ".gitattributes"))
	if err != nil {
		t.Fatalf("could not read .gitattributes: %v", err)
	}
	declared := map[string]bool{}
	for _, line := range strings.Split(string(body), "\n") {
		fields := strings.Fields(line)
		if len(fields) < 2 || strings.HasPrefix(fields[0], "#") {
			continue
		}
		for _, attr := range fields[1:] {
			if attr == "linguist-generated" || attr == "linguist-generated=true" {
				declared[fields[0]] = true
			}
		}
	}

	for _, file := range []string{
		// cidx security baseline
		"SECURITY-BASELINE.md",
		// cidx preset catalogue
		"docs/reference/catalogue.md",
	} {
		if !declared[file] {
			t.Errorf("%s is generated by a cidx command but .gitattributes does not mark it linguist-generated", file)
		}
	}
}
